import React, { useState, useEffect, useRef, useContext } from 'react';
import {
  Box,
  Typography,
  Card,
  Paper,
} from '@mui/material';
import { GoogleMap, Marker, useJsApiLoader } from '@react-google-maps/api';
import { useNavigate, useLocation } from 'react-router-dom';
import FormsBottomNavbar from './../Post Module/FormsBottomNavbar';
import CustomSearchBar from "./../Lease Module/CustomSearch";
import { BASE_URL } from './../../Api/ApiUrls';
import { AuthContext } from '../../AuthContext/AuthContext';

const GOOGLE_MAPS_API_KEY = "AIzaSyAZAU88Lr8CEkiFP_vXpkbnu1-g-PRigXU";

const containerStyle = {
  width: '100%',
  height: 'calc(100vh - 240px)',
};

const DEFAULT_CENTER = {
  lat: 17.3850,
  lng: 78.4867
};

// Define libraries outside the component
const libraries = ['places'];

const HomeServiceType = () => {
  const [vendors, setVendors] = useState([]);
  const [selectedWorker, setSelectedWorker] = useState(null);
  const [loading, setLoading] = useState(true);
   const { userId } = useContext(AuthContext); 

    const navigate = useNavigate();
  const location = useLocation();
  const mapRef = useRef(null);
   const [mapCenter, setMapCenter] = useState(DEFAULT_CENTER);
  const { isLoaded,loadError } = useJsApiLoader({
    id: 'google-map-script',
    googleMapsApiKey: GOOGLE_MAPS_API_KEY,
    libraries: libraries, // Use the constant here
  });
 // Get category from navigation state
  const category = location.state?.category || '';
  useEffect(() => {const fetchUserLocation = async () => {
      try {
        if (!userId) {
          setMapCenter(DEFAULT_CENTER);
          return;
        }
        
        const response = await fetch(`${BASE_URL}/users/${userId}/`);
        const userData = await response.json();
        
        if (userData.lat && userData.long) {
          setMapCenter({
            lat: parseFloat(userData.lat),
            lng: parseFloat(userData.long)
          });
        } else {
          setMapCenter(DEFAULT_CENTER);
        }
      } catch (error) {
        console.error("Error fetching user location:", error);
        setMapCenter(DEFAULT_CENTER);
      }
    };
    const fetchVendors = async () => {
      try {
        const response = await fetch(`${BASE_URL}/vendors/`);
        const data = await response.json();
        
        const filteredVendors = category 
          ? data.filter(vendor => 
              vendor.profession && 
              vendor.profession.toLowerCase().includes(category.toLowerCase()))
          : data;

        setVendors(filteredVendors);
      } catch (error) {
        console.error("Error fetching vendors:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchUserLocation();
    fetchVendors();

  }, [category, userId]);

   const onMapLoad = React.useCallback((map) => {
    mapRef.current = map;
    map.setCenter(mapCenter);
    map.setZoom(12);
  }, [mapCenter]);

  if (loadError) {
    return <Typography color="error">Error loading Google Maps</Typography>;
  }

  return (
    <Box
      sx={{
 pb: 7,
        maxWidth: 480,
        mx: "auto",
        position: 'relative',
        bgcolor: 'rgb(239, 231, 221)',
        minHeight: '100vh'
      }}
    >
      <Box
        sx={{
          position: 'sticky',
          top: 0,
          zIndex: 1000,
          bgcolor: 'rgb(239, 231, 221)',
          px: 1,
          py: 1,
        }}
      >
        <CustomSearchBar />
      </Box>

      <Box sx={{ px: 2, pt: 2 }}>
        <Typography variant="h6" fontWeight="bold" sx={{ mb: 1 }}>
          {category || 'All'} Services
        </Typography>
      </Box>

      {vendors.length === 0 && !loading && (
        <Box sx={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          height: '200px',
          px: 2,
          textAlign: 'center'
        }}>
          <Box sx={{
            backgroundColor: 'rgba(255, 255, 255, 0.9)',
            padding: '16px',
            borderRadius: '8px',
            textAlign: 'center'
          }}>
            <Typography variant="h6">
              No workers available
            </Typography>
            <Typography variant="body2" sx={{ mt: 1 }}>
              {category ? `We couldn't find any ${category} workers` : 'No workers found'}
            </Typography>
          </Box>
        </Box>
      )}

      {vendors.length > 0 && (
        <Box sx={{ px: 2, pb: 10 }}>
          {isLoaded ? (
            <Box sx={{ width: '100%', height: containerStyle.height }}>
              <GoogleMap
                mapContainerStyle={containerStyle}
                 center={mapCenter}
                 zoom={12}
                onLoad={onMapLoad}
                options={{
                  gestureHandling: 'greedy',
                  zoomControl: true,
                  mapTypeControl: false,
                  streetViewControl: false,
                  fullscreenControl: false,
                }}
              >
                {vendors.map((vendor) => {
                  const lat = parseFloat(vendor.lat);
                  const lng = parseFloat(vendor.long);
                  return (
                    lat && lng && (
                      <Marker
                        key={vendor.vendor_id}
                        position={{ lat, lng }}
                        onClick={() => setSelectedWorker(vendor)}
                      />
                    )
                  );
                })}
              </GoogleMap>
            </Box>
          ) : (
            <Typography sx={{ textAlign: 'center' }}>Loading map...</Typography>
          )}

          {selectedWorker && (
            <Box
              sx={{
                position: 'absolute',
                bottom: 250,
                left: 0,
                right: 0,
                px: 2,
                zIndex: 999,
              }}
            >
              <Card
                onClick={() => navigate(`/work-details/${selectedWorker.vendor_id}`)}
                sx={{
                  borderRadius: 3,
                  p: 2,
                  backgroundColor: '#fff',
                  boxShadow: 3,
                }}
              >
                <Box sx={{ display: 'flex', gap: 2 }}>
                  <img
                    src={`${BASE_URL}${selectedWorker.profile}`}
                    alt={selectedWorker.name}
                    style={{
                      width: 100,
                      height: 100,
                      borderRadius: 10,
                      objectFit: 'cover',
                    }}
                  />
                  <Box>
                    <Typography variant="subtitle1" fontWeight="bold">
                      {selectedWorker.profession}
                    </Typography>
                    <Typography variant="body2">Name: {selectedWorker.name}</Typography>
                    <Typography variant="body2">Mobile: {selectedWorker.mobile}</Typography>
                    <Typography variant="body2">Email: {selectedWorker.email}</Typography>
                    <Typography variant="body2">Experience: {selectedWorker.experience}+ year(s)</Typography>
                    <Typography variant="body2">⭐⭐⭐⭐</Typography>
                  </Box>
                </Box>
              </Card>
            </Box>
          )}
        </Box>
      )}

      <Paper sx={{ position: 'fixed', bottom: 0, left: 0, right: 0 }} elevation={3}>
        <FormsBottomNavbar />
      </Paper>
    </Box>
  );
};

export default HomeServiceType;
