import {
  Box,
  AppBar,
  Toolbar,
  IconButton,
  Typography,
  Container,
  Card,
  CardContent,
  CircularProgress,
  Button
} from '@mui/material';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import FormsBottomNavbar from "./../Post Module/FormsBottomNavbar";
import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { BASE_URL } from '../../Api/ApiUrls';

const MatchingBuyersPage = () => {
  const { propertyId } = useParams();
  const navigate = useNavigate();
  const [buyers, setBuyers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [categories, setCategories] = useState([]);
  const [users, setUsers] = useState([]);
  const [property, setProperty] = useState(null);

  const calculateDistance = (lat1, lon1, lat2, lon2) => {
    const R = 6371;
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a =
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
      Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  };

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);

        const propertiesResponse = await axios.get(`${BASE_URL}/property/`);
        const foundProperty = propertiesResponse.data.find(p => p.property_id == propertyId);
        if (!foundProperty) {
          setLoading(false);
          return;
        }
        setProperty(foundProperty);

        const categoriesResponse = await axios.get(`${BASE_URL}/property-category/`);
        setCategories(categoriesResponse.data);

        const enquiriesResponse = await axios.get(`${BASE_URL}/Enquiry/`);
        const allEnquiries = enquiriesResponse.data;

        const usersResponse = await axios.get(`${BASE_URL}/users/`);
        setUsers(usersResponse.data);

        const propertyCategory = categoriesResponse.data.find(cat => cat.category_id == foundProperty.category_id)?.category;

        const parseCoord = (coord) => {
          if (!coord) return null;
          const cleaned = coord.replace(/"/g, '').replace(':', '.');
          return parseFloat(cleaned);
        };

        const propLat = parseCoord(foundProperty.lat);
        const propLong = parseCoord(foundProperty.long);

        const matchingBuyers = allEnquiries.filter(enquiry => {
          const enquiryUser = usersResponse.data.find(user => user.user_id == enquiry.user_id);
          if (!enquiryUser) return false;

          const typeMatch = enquiry.property_type && propertyCategory &&
            enquiry.property_type.toLowerCase() === propertyCategory.toLowerCase();

          const budgetMatch = (() => {
            if (!foundProperty.price) return false;
            if (enquiry.min_budget && enquiry.max_budget) {
              return foundProperty.price >= enquiry.min_budget && foundProperty.price <= enquiry.max_budget;
            }
            if (enquiry.min_budget && !enquiry.max_budget) {
              return foundProperty.price >= enquiry.min_budget;
            }
            if (!enquiry.min_budget && enquiry.max_budget) {
              return foundProperty.price <= enquiry.max_budget;
            }
            if (enquiry.budget) {
              return foundProperty.price >= enquiry.budget * 0.8 && foundProperty.price <= enquiry.budget * 1.2;
            }
            return false;
          })();

          const locationMatch = (() => {
            if (!propLat || !propLong || !enquiry.lat || !enquiry.long) return false;
            try {
              const enqLat = parseFloat(enquiry.lat);
              const enqLong = parseFloat(enquiry.long);
              const distance = calculateDistance(propLat, propLong, enqLat, enqLong);
              return distance <= 10;
            } catch {
              return false;
            }
          })();

          return typeMatch && budgetMatch && locationMatch;
        }).map(enquiry => ({
          ...enquiry,
          user: usersResponse.data.find(user => user.user_id == enquiry.user_id),
          formattedBudget: formatBudgetDisplay(enquiry),
          distance: (() => {
            if (!propLat || !propLong || !enquiry.lat || !enquiry.long) return 'N/A';
            try {
              const enqLat = parseFloat(enquiry.lat);
              const enqLong = parseFloat(enquiry.long);
              return `${calculateDistance(propLat, propLong, enqLat, enqLong).toFixed(1)} km`;
            } catch {
              return 'N/A';
            }
          })()
        }));

        setBuyers(matchingBuyers);
      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [propertyId]);

  const formatBudgetDisplay = (enquiry) => {
    if (enquiry.min_budget && enquiry.max_budget) {
      return `₹${(enquiry.min_budget / 100000).toLocaleString()}L - ₹${(enquiry.max_budget / 100000).toLocaleString()}L`;
    }
    if (enquiry.min_budget && !enquiry.max_budget) {
      return `₹${(enquiry.min_budget / 10000000).toLocaleString()}Cr+`;
    }
    if (!enquiry.min_budget && enquiry.max_budget) {
      return `Up to ₹${(enquiry.max_budget / 100000).toLocaleString()}L`;
    }
    return enquiry.budget ? `₹${(enquiry.budget / 100000).toLocaleString()}L` : "Not specified";
  };

  if (loading) {
    return <Box textAlign="center" mt={4}><CircularProgress /></Box>;
  }

  if (!property) return <div>Property not found</div>;

  return (
     <Box
      sx={{
        minHeight: '100vh',
        pb: 8,
        backgroundImage:
          'linear-gradient(145deg, rgba(232,224,208,0.95), rgba(216,204,186,0.95))',
      }}
    >
      {/* Top App Bar */}
      <AppBar position="static" sx={{ backgroundColor: '#000' }}>
        <Toolbar>
          <IconButton edge="start" color="inherit" onClick={() => navigate(-1)}>
            <ArrowBackIosNewIcon />
          </IconButton>
          <Typography variant="h6" sx={{ ml: 2 }}>
            Matching Buyers ({buyers.length})
          </Typography>
        </Toolbar>
      </AppBar>

      {/* Matching Buyers Container */}
      <Container sx={{ py: 3 }}>

        {buyers.length === 0 ? (
          <Typography align="center" color="text.secondary" mt={5}>
            No matching buyers found.
          </Typography>
        ) : (
          buyers.map((buyer) => (
            <Card
              key={buyer.enqid}
              sx={{
                mb: 3,
                p: 2,
                borderRadius: 3,
                boxShadow: 4,
                backgroundColor: '#fff',
              }}
            >
              <Typography variant="h5" align='center' sx={{ mt: 2,mb: 2 }}>
            Matching Buyers Details
          </Typography>

              <Card
                variant="outlined"
                sx={{
                  p: 2,
                  borderRadius: 2,
                  backgroundColor: '#f9f9f9',
                  boxShadow: 1,
                }}
              >
                 <Typography variant="body2">
                  <b>Name</b> {buyer.user?.username || 'Anonymous Buyer'}
                </Typography>
                 <Typography variant="body2">
                    <b>Email</b> {buyer.user?.email || 'N/A'}
                </Typography>
                <Typography variant="body2">
                  <b>Looking for:</b> {buyer.property_type}
                </Typography>
                <Typography variant="body2">
                  <b>Preferred Area:</b> {buyer.area}
                </Typography>
                <Typography variant="body2">
                  <b>Budget:</b> {buyer.formattedBudget}
                </Typography>
                <Typography variant="body2">
                  <b>Distance from property:</b> {buyer.distance}
                </Typography>
                <Typography
                  variant="caption"
                  color="text.secondary"
                  sx={{ display: 'block', mt: 1 }}
                >
                  Enquiry Date: {new Date(buyer.created_at).toLocaleDateString()}
                </Typography>

                 <Box textAlign="center">
                <Box
                  onClick={() => {
                    const phone = buyer.user?.mobile_no || 'N/A';
                    navigator.clipboard.writeText(phone);
                    alert(`Phone number ${phone} copied!`);
                  }}
                  sx={{
                    backgroundColor: '#e53935',
                    color: '#fff',
                    py: 1,
                    mt: 2,
                    borderRadius: '20px',
                    fontWeight: 500,
                    cursor: 'pointer',
                    '&:hover': {
                      backgroundColor: '#d32f2f',
                    },
                  }}
                >
                  📞 {buyer.user?.mobile_no || 'N/A'} (Tap to Copy)
                </Box>
              </Box>
              </Card>

              
            </Card>
          ))
        )}
      </Container>

      {/* Bottom Navbar */}
      <Box sx={{ position: 'fixed', bottom: 0, left: 0, right: 0 }}>
        <FormsBottomNavbar />
      </Box>
    </Box>
  );
};
export default MatchingBuyersPage;
