import React, { useState, useContext, useEffect } from "react";
import axios from "axios";
import {
  Box,
  Button,
  MenuItem,
  Modal,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
  Paper,
  Divider,
  InputAdornment,
} from "@mui/material";
import HomeIcon from "@mui/icons-material/Home";
import LocationOnIcon from "@mui/icons-material/LocationOn";
import { BASE_URL } from "./Api/ApiUrls";
import { AuthContext } from "./AuthContext/AuthContext";

const propertyTypes = [
  "Plot/land", "Commercial land/plot", "Rent with duplex building",
  "Duplex house", "Rental building", "Pg-offices", "Flat", "Villa",
  "Commercial building", "Apartment", "Others"
];

const budgetOptions = [
  { label: 'Select budget range', value: '' },
  { label: 'Under 10L', value: '0-1000000' },
  { label: '10L - 20L', value: '1000000-2000000' },
  { label: '20L - 30L', value: '2000000-3000000' },
  { label: '30L - 40L', value: '3000000-4000000' },
  { label: '40L - 50L', value: '4000000-5000000' },
  { label: '50L - 60L', value: '5000000-6000000' },
  { label: '60L - 70L', value: '6000000-7000000' },
  { label: '70L - 80L', value: '7000000-8000000' },
  { label: '80L - 90L', value: '8000000-9000000' },
  { label: '90L - 1Cr', value: '9000000-10000000' },
  { label: '1Cr - 2Cr', value: '10000000-20000000' },
  { label: '2Cr+', value: '20000000-99999999' }
];

const CustomerInterestForm = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const { userId, logout } = useContext(AuthContext);

  const [formData, setFormData] = useState({
    area: "",
    propertyType: "",
    budgetRange: "",
    min_budget: null,
    max_budget: null,
    latitude: null,
    longitude: null,
  });

  const [predictions, setPredictions] = useState([]);
  const [inputValue, setInputValue] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [hasExistingEnquiry, setHasExistingEnquiry] = useState(false);
  const [loading, setLoading] = useState(true);
  const [placesService, setPlacesService] = useState(null);

  // Load Google Maps script
  useEffect(() => {
    const script = document.createElement("script");
    script.src = `https://maps.googleapis.com/maps/api/js?key=AIzaSyAZAU88Lr8CEkiFP_vXpkbnu1-g-PRigXU&libraries=places`;
    script.async = true;
    script.defer = true;
    script.onload = () => {
      setPlacesService(new window.google.maps.places.PlacesService(document.createElement("div")));
    };
    document.head.appendChild(script);
    return () => document.head.removeChild(script);
  }, []);

  // Check for existing enquiries
  useEffect(() => {
    const checkExistingEnquiry = async () => {
      try {
        // Fetch all enquiries for this user
        const response = await axios.get(`${BASE_URL}/Enquiry/`);
        const userEnquiries = response.data.filter(
          enquiry => enquiry.user_id == userId
        );
console.log("User Enquiries:", userEnquiries);
        if (userEnquiries.length === 0) {
          // Only show form if user has no existing enquiries
          const timer = setTimeout(() => {
            setShowForm(true);
          }, 60000);
          return () => clearTimeout(timer);
        } else {
          setHasExistingEnquiry(true);
        }
      } catch (error) {
        console.error("Error checking existing enquiries:", error);
        // Fallback - show form anyway
        const timer = setTimeout(() => {
          setShowForm(true);
        }, 60000);
        return () => clearTimeout(timer);
      } finally {
        setLoading(false);
      }
    };

    if (userId) {
      checkExistingEnquiry();
    }
  }, [userId]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleBudgetRangeChange = (e) => {
    const value = e.target.value;
    const [min, max] = value.split('-').map(Number);
    setFormData({
      ...formData,
      budgetRange: value,
      min_budget: min || null,
      max_budget: max || null,
    });
  };

  // const handleAreaChange = (e) => {
  //   const value = e.target.value;
  //   setInputValue(value);
  //   setFormData(prev => ({ ...prev, area: value, latitude: null, longitude: null }));

  //   if (value.length > 2 && window.google) {
  //     const service = new window.google.maps.places.AutocompleteService();
  //     service.getQueryPredictions({ input: value, componentRestrictions: { country: 'in' } }, (predictions, status) => {
  //       if (status === window.google.maps.places.PlacesServiceStatus.OK) {
  //         setPredictions(predictions);
  //       } else {
  //         setPredictions([]);
  //       }
  //     });
  //   }
  // };


  const handleAreaChange = (e) => {
  const value = e.target.value;
  setInputValue(value);
  setFormData(prev => ({ ...prev, area: value, latitude: null, longitude: null }));

  // Check if Google Maps API is loaded and AutocompleteService is available
  if (value.length > 2 && window.google && window.google.maps && window.google.maps.places) {
    try {
      const service = new window.google.maps.places.AutocompleteService();
      service.getQueryPredictions({ input: value, componentRestrictions: { country: 'in' } }, (predictions, status) => {
        if (status === window.google.maps.places.PlacesServiceStatus.OK) {
          setPredictions(predictions || []);
        } else {
          setPredictions([]);
        }
      });
    } catch (error) {
      console.error("Error with Google Places Autocomplete:", error);
      setPredictions([]);
    }
  } else {
    setPredictions([]);
  }
};
  const handleSelectSuggestion = (prediction) => {
    setInputValue(prediction.description);
    setPredictions([]);

    placesService?.getDetails({ placeId: prediction.place_id, fields: ['geometry'] }, (place, status) => {
      if (status === window.google.maps.places.PlacesServiceStatus.OK) {
        const location = place.geometry.location;
        setFormData(prev => ({
          ...prev,
          area: prediction.description,
          latitude: location.lat(),
          longitude: location.lng(),
        }));
      }
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.latitude || !formData.longitude) {
      alert('Please select a valid area from the dropdown.');
      return;
    }

    const payload = {
      user_id: userId,
      area: formData.area?.trim(),
      property_type: formData.propertyType,
      min_budget: formData.min_budget,
      max_budget: formData.max_budget,
      lat: formData.latitude,
      long: formData.longitude,
    };

    try {
      await axios.post(`${BASE_URL}/Enquiry/`, payload);
      alert("Enquiry submitted!");
      setShowForm(false);
      setHasExistingEnquiry(true);
    } catch (error) {
      console.error("API Error:", error);
      alert("Submission failed.");
    }
  };

  if (loading || hasExistingEnquiry || !userId) {
    return null;
  }

  return (
    <Modal open={showForm} sx={{ backdropFilter: "blur(3px)" }}>
      <Paper
        component="form"
        onSubmit={handleSubmit}
        sx={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: isMobile ? "90%" : 450,
          bgcolor: "background.paper",
          borderRadius: 3,
          boxShadow: 24,
          p: 4,
          outline: "none"
        }}
      >
        <Box textAlign="center" mb={3}>
          <HomeIcon color="primary" sx={{ fontSize: 40 }} />
          <Typography variant="h5" mt={1} fontWeight="600">Property Preferences</Typography>
          <Typography variant="body2" color="text.secondary">Let us know what you're looking for</Typography>
        </Box>

        <Divider sx={{ mb: 3 }} />

        <Box position="relative">
          <TextField
            fullWidth
            label="Preferred Area"
            value={inputValue}
            onChange={handleAreaChange}
            required
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  <LocationOnIcon color="action" />
                </InputAdornment>
              ),
            }}
            sx={{ mb: 2 }}
          />
          {predictions.length > 0 && (
            <Paper elevation={3} sx={{ position: "absolute", zIndex: 1300, width: "100%", maxHeight: 200, overflowY: "auto" }}>
              {predictions.map(prediction => (
                <MenuItem key={prediction.place_id} onClick={() => handleSelectSuggestion(prediction)}>
                  {prediction.description}
                </MenuItem>
              ))}
            </Paper>
          )}
        </Box>

        <TextField
          select
          fullWidth
          label="Property Type"
          name="propertyType"
          value={formData.propertyType}
          onChange={handleChange}
          required
          sx={{ mb: 2 }}
        >
          {propertyTypes.map(type => (
            <MenuItem key={type} value={type}>{type}</MenuItem>
          ))}
        </TextField>

        <TextField
          select
          fullWidth
          label="Budget Range"
          name="budgetRange"
          value={formData.budgetRange}
          onChange={handleBudgetRangeChange}
          required
          sx={{ mb: 3 }}
        >
          {budgetOptions.map(option => (
            <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>
          ))}
        </TextField>

        <Box display="flex" justifyContent="space-between">
          <Button variant="outlined" onClick={() => setShowForm(false)} sx={{ width: '45%', py: 1.5, borderRadius: 2 }}>Cancel</Button>
          <Button variant="contained" type="submit" sx={{ width: '45%', py: 1.5, borderRadius: 2, fontWeight: 'bold' }}>Submit</Button>
        </Box>
      </Paper>
    </Modal>
  );
};

export default CustomerInterestForm;